-- ─── Talk questions, written from the lesson vocabulary ─────────────────────
-- Run in the Supabase SQL Editor (or `supabase db query --linked -f …`).
--
-- Free Talk's "Talk questions" no longer call an AI service. These are
-- speaking questions written for each lesson from that lesson's own words
-- (Palestinian and MSA), in Arabic script and transliteration, with an
-- English line, a hint (how the answer starts) and the lesson words used.
-- The page picks from the lessons the student has started or finished.
--
-- Read by anyone (like the lessons); nobody writes from the app.
-- Safe to run twice: the seeded questions are replaced, not doubled.

create table if not exists public.arabic_talk_questions (
  id          uuid primary key default gen_random_uuid(),
  lesson_id   text not null references public.arabic_lessons(id) on delete cascade,
  dialect     text not null check (dialect in ('levantine', 'msa')),
  tense       text not null check (tense in ('past', 'present')),
  q_ar        text not null,
  q_tr        text not null,
  en          text not null,
  hint_ar     text not null default '',
  hint_tr     text not null default '',
  words       jsonb not null default '[]'::jsonb,   -- [{ar, tr}] lesson words the question uses
  order_index int not null default 0,
  source      text not null default 'seed',
  created_at  timestamptz not null default now()
);
create index if not exists arabic_talk_questions_lesson_idx on public.arabic_talk_questions (lesson_id);

alter table public.arabic_talk_questions enable row level security;
drop policy if exists arabic_talk_questions_read on public.arabic_talk_questions;
create policy arabic_talk_questions_read on public.arabic_talk_questions
  for select to anon, authenticated using (true);

delete from public.arabic_talk_questions where source = 'seed';

